cc.Class({
    extends: cc.Component,
    properties: {
        layoutParent: cc.Node,
        sfResult:[cc.SpriteFrame],
        listIcon:[cc.Sprite]
    },
    onLoad: function () {
        cc.BacaratController.getInstance().setLichsuView(this);
    },
    initListLichsu: function (data) {
        if (data.length === 0) {
            return;
        }
        // try {
        //     this.clearList();
        // } catch (e) {
        //     console.log(e);
        // }
        
        data = data.slice(0,12);
        
        for (let index = data.length -1; index >= 0; index--) {
            switch (data[index].BigGateIDWin) {
                case 2: //player
                    
                    this.listIcon[index].spriteFrame = this.sfResult[0];
                    break;
                case 3: //tie
                    this.listIcon[index].spriteFrame = this.sfResult[1];
                    break;
                case 4: //banker
                    this.listIcon[index].spriteFrame = this.sfResult[2];
                    break;
            
                default:
                    break;
            }
            if (index == 0) {
                cc.tween(this.listIcon[index].node).repeatForever(cc.tween().sequence(cc.tween().to(0.5, {
                    scale: 0.9
                  }, {
                    easing: cc.easing.sineOut
                  }), cc.tween().to(0.5, {
                    scale: 1.0
                  }, {
                    easing: cc.easing.sineOut
                  }))).start();
            }
            
        }
        this.node.active = true;
    },
    clearList: function () {
        this.layoutParent.removeAllChildren(true);
    },
    onDestroy: function () {
        try {
            cc.BacaratController.getInstance().setLichsuView(null);
        } catch (e) {

        }
    }
});